        for sku, quantity in items:
            if self.inventory.get_quantity(sku) < quantity:
                return False
        return True

    def apply_discount(self, subtotal: float, code: str) -> float:
        pct = self.discount_codes.get(code, 0)
        return round(subtotal * (1 - pct), 2)

