        if discount_code:
            subtotal = self.apply_discount(subtotal, discount_code)
        tax = compute_tax(subtotal)
        for sku, qty in items:
            self.inventory.remove_item(sku, qty)
        total = subtotal + tax
        self._log(f"order processed: total={total}")
        return total

