    if len(text) <= length:
        return text
    return text[: length - len(suffix)] + suffix


def pluralize(count: int, singular: str, plural: str = None) -> str:
    if count == 1:
        return f"{count} {singular}"
    return f"{count} {plural or singular + 's'}"
EOF
